  it('feeds a schema-rejection ToolResponse back as a tool_result so the model can retry', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup',
        description: 'lookup',
        inputSchema: {type: 'object', properties: {q: {type: 'string'}}, required: ['q']},
      },
      async input => `result: ${String(input.q)}`
    );

    let rejectionSeenByModel = '';
    let callCount = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        callCount += 1;
        if (callCount === 1) {
          yield {type: 'tool_use', toolCall: {id: 'c1', name: 'lookup', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        if (callCount === 2) {
          const lastMsg = params.messages.at(-1) as ToolResultMessage | undefined;
          const toolResult = lastMsg?.content[0];
          rejectionSeenByModel = toolResult?.content ?? '';
          yield {type: 'tool_use', toolCall: {id: 'c2', name: 'lookup', input: {q: 'test'}}};
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        yield {type: 'text', text: 'done'};
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const result = await createChatOrchestrator(provider, promptBuilder, registry).processMessage(createSession('ask'));

    expect(result).toBe('done');
    expect(rejectionSeenByModel).toMatch(/q/);
  });
});

