import Ajv from './node_modules/ajv/dist/ajv.js';
const ajv = new Ajv({strict: false, validateFormats: false});

// From registry.ts formatValidationErrors
function formatValidationErrors(errors) {
  return errors.map(e => `${e.instancePath ? e.instancePath + ' ' : ''}${e.message ?? 'invalid'}`.trim()).join('; ');
}

// Compile the ssn_lookup schema (as done at register time)
const schema = {type: 'object', properties: {ssn: {type: 'string'}}, required: ['ssn']};
const validate = ajv.compile(schema);

// Execute with wrong-typed input
const isValid = validate({ssn: 123456789});
console.log('isValid:', isValid);
const errors = (validate.errors ?? []);
console.log('errors:', JSON.stringify(errors));
const result = formatValidationErrors(errors);
console.log('result:', JSON.stringify(result));
console.log('includes ssn:', result.includes('ssn'));
console.log('includes string:', result.includes('string'));
console.log('includes 123456789:', result.includes('123456789'));
EOF

