       import Ajv from 'ajv';
       import type {ValidateFunction} from 'ajv';

       interface AjvError {
         instancePath?: string;
         keyword?: string;
         message?: string;
       }

       const ajv = new Ajv({strictSchema: false, strictTypes: false, validateFormats: false});

       function formatValidationErrors(errors: AjvError[]): string {
         return errors.map(e => `${e.instancePath ? e.instancePath + ' ' : ''}${e.message ?? 'invalid'}`.trim()).join('; ');
       }

       export class ToolRegistry {
         private readonly tools = new Map<string, StoredTool>();
         private readonly schemaCache = new WeakMap<object, ValidateFunction>();

         register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
           const resolved = this.resolveDefinition(definition);
           let compiledValidator: ValidateFunction | undefined;
           if (typeof definition !== 'function') {
             try {
               compiledValidator = ajv.compile(resolved.inputSchema as object);
             } catch (err) {
               throw new Error(`Tool "${resolved.name}": invalid inputSchema — ${(err as Error).message}`, {cause: err});
             }
           }
           this.tools.set(resolved.name, {definitionSource: definition, execute, compiledValidator});
         }

         private resolveValidator(source: ToolDefinitionSource): ValidateFunction {
           const resolved = this.resolveDefinition(source);
           const schema = resolved.inputSchema as object;
           const cached = this.schemaCache.get(schema);
           if (cached) return cached;
           const compiled = ajv.compile(schema);
           this.schemaCache.set(schema, compiled);
           return compiled;
         }

         /** See specs/hal-engine-tool-input-validation/spec.md for the full contract. */
         async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
           const tool = this.tools.get(name);
           if (!tool) {
             log.warn('tool', 'tool not found', {name});
             throw new Error(`Unknown tool: ${name}`);
           }
           const validate = tool.compiledValidator ?? this.resolveValidator(tool.definitionSource);
           if (!validate(input)) {
             const errors = (validate.errors ?? []) as AjvError[];
             const result = formatValidationErrors(errors);
             log.warn('tool', 'input validation failed', {
               name,
               errors: errors.map(e => ({path: e.instancePath, keyword: e.keyword, message: e.message})),
             });
             return {result};
           }
           log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
           const rawResult = await tool.execute(input, context);
           const response = normalizeToolResponse(rawResult);
           log.info('tool', 'execution complete', {
             name, rawType: typeof rawResult,
             clientMessageCount: response.clientMessages?.length ?? 0,
             clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
             suppressAssistantResponse: response.suppressAssistantResponse ?? false,
           });
           return response;
         }
       }
